/**
 * Every dropdown a window scene's top bar opens, placed like the app's
 * Dropdown (src/ui/Dropdown.tsx) against the window's right edge, so the same
 * set works in a window of any width.
 */
import type { ReactNode } from "react";
import { Monitor, Settings } from "lucide-react";
import { PANEL } from "./Chrome";
import type { ToolId } from "./Interactive";
import { NewSessionPanel } from "./NewSessionPanel";
import { NotificationsPanel, PortsPanel, QuickChatPanel, UsagePanel } from "./Panels";
import { TasksPanel } from "./TasksPanel";

/**
 * Remote desktop: the Dropdown App.tsx renders inline (width 180, align end,
 * compact) with Open, for the saved connection, and Settings. Its button
 * ends 197px from the right edge.
 */
function RemotePanel() {
  return (
    <div className="menu menu-panel menu-compact" style={{ right: 197, top: PANEL.top, left: "auto", width: 180 }}>
      <button type="button" className="menu-item">
        <Monitor size={16} strokeWidth={1.9} />
        Open
      </button>
      <button type="button" className="menu-item">
        <Settings size={16} strokeWidth={1.9} />
        Settings
      </button>
    </div>
  );
}

/**
 * The dropdowns for a window `height` px tall. `agentMenu` opens the New
 * session form with its agent list showing.
 */
export function windowPanels({ height, agentMenu = false }: { height: number; agentMenu?: boolean }): Partial<Record<ToolId, ReactNode>> {
  return {
    tasks: <TasksPanel right={PANEL.edge} top={PANEL.top} />,
    // The Quick Chat terminal is min(440px, 48vh) tall in the app.
    chat: <QuickChatPanel termHeight={Math.min(440, Math.round(height * 0.48))} />,
    remote: <RemotePanel />,
    ports: <PortsPanel />,
    usage: <UsagePanel />,
    bell: <NotificationsPanel />,
    new: <NewSessionPanel right={PANEL.edge} top={PANEL.topNew} initialMenu={agentMenu} />,
  };
}
